import { describe, test, expect } from "vitest";
import { parseWatchTarget, formatWatchTarget, allCheckNames } from "../src/watch.ts";

describe("parseWatchTarget", () => {
  test("owner/repo#N", () => {
    expect(parseWatchTarget("yonatangross/orchestkit#4420")).toEqual({
      owner: "yonatangross",
      repo: "orchestkit",
      number: 4420,
    });
  });

  test("owner/repo N, with or without a hash", () => {
    expect(parseWatchTarget("  vercel/next.js 123 ")).toEqual({ owner: "vercel", repo: "next.js", number: 123 });
    expect(parseWatchTarget("vercel/next.js #123")).toEqual({ owner: "vercel", repo: "next.js", number: 123 });
  });

  test("a GitHub PR URL", () => {
    expect(parseWatchTarget("https://github.com/anthropics/claude-code/pull/91870/checks")).toEqual({
      owner: "anthropics",
      repo: "claude-code",
      number: 91870,
    });
  });

  test("rejects anything else", () => {
    for (const bad of ["", "   ", "orchestkit#1", "a/b#", "a/b#0", "a/b#-3", "a/b#12x", "a b 12", undefined, null]) {
      expect(parseWatchTarget(bad)).toBeNull();
    }
  });

  test("format round-trips", () => {
    const t = { owner: "o", repo: "r", number: 7 };
    expect(parseWatchTarget(formatWatchTarget(t))).toEqual(t);
  });
});

describe("allCheckNames", () => {
  test("distinct names in first-seen order", () => {
    expect(
      allCheckNames([{ name: "build" }, { name: "lint" }, { name: "build" }, { name: "test" }])
    ).toEqual(["build", "lint", "test"]);
  });

  test("no runs, no names", () => {
    expect(allCheckNames([])).toEqual([]);
  });
});
